/**
 * Learn-Index — Build a topic→agent-relevance index for the learnings store.
 *
 * Solves the P-RES-002 anti-pattern PAN currently ships: workflow files say
 * "Also see learnings/universal/" and the agent skim-loads ~25 files into
 * context every plan/exec turn. Distractor density (per Chroma 2025) degrades
 * agent performance even at modest token counts.
 *
 * The index lets agents load only the topics relevant to their role at the
 * current phase, with token budgets visible.
 *
 * Generated by: `pan-tools learn build-index`
 * Read by:      `pan-tools learn topics-for --agent <name>`
 * Stored at:    pan-wizard-core/learnings/index.json
 */

const fs = require('fs');
const path = require('path');
const { collectAllPatterns } = require('./learn-lint.cjs');

const CHARS_PER_TOKEN = 4;

const INDEX_PATH_REL = path.join('pan-wizard-core', 'learnings', 'index.json');

/**
 * Static topic→agent-role relevance table. Curated, not heuristic — these
 * judgments come from "what does each agent role NEED to know to do its job
 * well?" (per the agent definitions in agents/pan-{planner,executor,verifier,
 * reviewer,plan-checker}.md).
 *
 * Values: 'high' = always load; 'medium' = load when relevant phase domain
 * matches; 'low' = load only when explicitly cited.
 *
 * If a topic is missing from the table, default is medium for executor and
 * low for the others (assumes new topics are mostly executor-side patterns
 * unless tagged otherwise).
 */
const RELEVANCE = {
  // Planning-time concerns
  'design-process':       { planner: 'high',   executor: 'low',    verifier: 'low',    reviewer: 'medium' },
  'schema-design':        { planner: 'high',   executor: 'medium', verifier: 'medium', reviewer: 'medium' },
  'composition':          { planner: 'high',   executor: 'medium', verifier: 'low',    reviewer: 'medium' },
  'dag-scheduler':        { planner: 'high',   executor: 'medium', verifier: 'low',    reviewer: 'medium' },
  'data-driven-design':   { planner: 'high',   executor: 'medium', verifier: 'low',    reviewer: 'medium' },
  'vendor-pattern':       { planner: 'medium', executor: 'low',    verifier: 'low',    reviewer: 'medium' },
  'phase-locking':        { planner: 'high',   executor: 'low',    verifier: 'low',    reviewer: 'low' },

  // Execution-time concerns
  'atomic-state':         { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'medium' },
  'binary-io':            { planner: 'low',    executor: 'high',   verifier: 'medium', reviewer: 'low' },
  'concurrency':          { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'medium' },
  'streaming-io':         { planner: 'low',    executor: 'high',   verifier: 'medium', reviewer: 'low' },
  'io-patterns':          { planner: 'low',    executor: 'high',   verifier: 'medium', reviewer: 'low' },
  'parser-design':        { planner: 'medium', executor: 'high',   verifier: 'medium', reviewer: 'medium' },
  'error-handling':       { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'high' },
  'error-paths':          { planner: 'low',    executor: 'high',   verifier: 'high',   reviewer: 'high' },
  'invariants':           { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'high' },
  'numeric-edge-cases':   { planner: 'low',    executor: 'high',   verifier: 'high',   reviewer: 'medium' },
  'unicode':              { planner: 'low',    executor: 'high',   verifier: 'medium', reviewer: 'low' },
  'glob-semantics':       { planner: 'low',    executor: 'medium', verifier: 'medium', reviewer: 'low' },
  'comment-syntax':       { planner: 'low',    executor: 'medium', verifier: 'low',    reviewer: 'medium' },
  'output-conventions':   { planner: 'low',    executor: 'high',   verifier: 'medium', reviewer: 'low' },
  'pipe-friendly-cli':    { planner: 'medium', executor: 'high',   verifier: 'low',    reviewer: 'low' },
  'empirical-spike':      { planner: 'high',   executor: 'medium', verifier: 'low',    reviewer: 'medium' },
  'idempotency':          { planner: 'high',   executor: 'high',   verifier: 'high',   reviewer: 'high' },
  'secret-handling':      { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'high' },

  // Verification-time concerns
  'test-patterns':        { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'high' },
  'test-strategy':        { planner: 'high',   executor: 'medium', verifier: 'high',   reviewer: 'high' },

  // Field-harvest 2026-07 (docs/FIELD-HARVEST-2026-07.md)
  'live-path-honesty':    { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'high' },
  'test-integrity':       { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'high' },
  'adversarial-verification': { planner: 'medium', executor: 'low', verifier: 'high',  reviewer: 'high' },
  'integration-verification': { planner: 'high', executor: 'low',  verifier: 'high',   reviewer: 'medium' },
  'single-source-of-truth': { planner: 'high', executor: 'high',   verifier: 'medium', reviewer: 'high' },
  'migration-safety':     { planner: 'high',   executor: 'high',   verifier: 'medium', reviewer: 'high' },
  'flaky-triage':         { planner: 'low',    executor: 'medium', verifier: 'high',   reviewer: 'medium' },
  'external-tool-truth':  { planner: 'low',    executor: 'high',   verifier: 'high',   reviewer: 'low' },
  'golden-sets':          { planner: 'high',   executor: 'medium', verifier: 'high',   reviewer: 'medium' },
  'harness-isolation':    { planner: 'high',   executor: 'medium', verifier: 'low',    reviewer: 'low' },
  'workaround-catalog':   { planner: 'low',    executor: 'high',   verifier: 'medium', reviewer: 'low' },
  'service-security':     { planner: 'medium', executor: 'high',   verifier: 'high',   reviewer: 'high' },
  'mcp-security':         { planner: 'medium', executor: 'medium', verifier: 'medium', reviewer: 'high' },
  'audit-convergence':    { planner: 'high',   executor: 'low',    verifier: 'high',   reviewer: 'high' },
  'fix-campaigns':        { planner: 'high',   executor: 'medium', verifier: 'high',   reviewer: 'high' },

  // PAN-internal (loaded only by PAN's own dev sessions)
  'experiment-runner':    { planner: 'low',    executor: 'low',    verifier: 'low',    reviewer: 'low' },
  'external-research':    { planner: 'medium', executor: 'low',    verifier: 'low',    reviewer: 'medium' },
  'pan-dev-bugs':         { planner: 'low',    executor: 'low',    verifier: 'low',    reviewer: 'low' },
  'loop-design':          { planner: 'medium', executor: 'low',    verifier: 'low',    reviewer: 'low' },
};

/**
 * Build the index from the on-disk learnings store.
 */
function buildIndex(sourceRoot) {
  const all = collectAllPatterns(sourceRoot);
  const byTopic = new Map();
  for (const p of all) {
    const key = `${p.scope}/${p.topic}`;
    if (!byTopic.has(key)) {
      byTopic.set(key, {
        name: p.topic,
        scope: p.scope,
        file: path.relative(sourceRoot, p.file).replace(/\\/g, '/'),
        patterns: [],
        size_bytes: 0,
        size_tokens_est: 0,
      });
    }
    const entry = byTopic.get(key);
    entry.patterns.push(p.id);
  }

  for (const [, entry] of byTopic) {
    const abs = path.join(sourceRoot, entry.file);
    try {
      const stat = fs.statSync(abs);
      entry.size_bytes = stat.size;
      entry.size_tokens_est = Math.ceil(stat.size / CHARS_PER_TOKEN);
    } catch {
      entry.size_bytes = 0;
      entry.size_tokens_est = 0;
    }
    const rel = RELEVANCE[entry.name] || { planner: 'low', executor: 'medium', verifier: 'low', reviewer: 'low' };
    entry.agent_relevance = rel;
  }

  const topics = [...byTopic.values()].sort((a, b) => {
    if (a.scope !== b.scope) return a.scope.localeCompare(b.scope);
    return a.name.localeCompare(b.name);
  });

  return {
    schema_version: 1,
    generated_at: new Date().toISOString(),
    topics,
    totals: {
      topics: topics.length,
      patterns: topics.reduce((s, t) => s + t.patterns.length, 0),
      size_bytes: topics.reduce((s, t) => s + t.size_bytes, 0),
      size_tokens_est: topics.reduce((s, t) => s + t.size_tokens_est, 0),
    },
  };
}

/**
 * Write the index to disk.
 */
function writeIndex(sourceRoot, index) {
  const filePath = path.join(sourceRoot, INDEX_PATH_REL);
  fs.writeFileSync(filePath, JSON.stringify(index, null, 2) + '\n');
  return filePath;
}

/**
 * Read the index from disk; build it if missing.
 */
function readIndex(sourceRoot) {
  const filePath = path.join(sourceRoot, INDEX_PATH_REL);
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
  } catch {
    return buildIndex(sourceRoot);
  }
}

// ─── Cue ranking (memory optimisation O5) ───────────────────────────────────
//
// The role ranking loads the same topics whatever the task, filling the budget
// smallest-first, so a large topic the task needs (migration-safety for a
// migration) drops out. With a cue — the phase objective and the files it
// touches — topics are matched to the task: the cue's words against each topic's
// name, pattern summaries and rules. Lexical, like `memory select`'s scorer, with
// two changes topic text needs: common words are ignored, and a word meets its
// own inflections (plurals fold; "corrupting" meets "corrupt", "parsed" "parse").

const CUE_STOPWORDS = new Set((
  'the and for with that this from into onto over under when then than them they their there these those '
  + 'are was were been being have has had not but all any each every per its our your you who what which '
  + 'can could should would will shall may might must also only just very more most less such same other '
  + 'add adds added adding make makes made making use uses used using new old get gets set sets run runs '
  + 'fix fixes fixed one two way ways out off how why where while after before about again still both '
  + 'file files code thing things project phase plan plans task tasks work works working change changes'
).split(' '));

/**
 * Fold a plural: "retries" → "retry", "classes" → "class", "matches" → "match",
 * "failures" → "failure", "cases" → "case"; "class" and "status" stay.
 */
function foldPlural(w) {
  if (w.length > 4 && w.endsWith('ies')) return `${w.slice(0, -3)}y`;
  if (w.length > 5 && w.endsWith('sses')) return w.slice(0, -2);
  if (w.length > 4 && /(x|z|ch|sh)es$/.test(w)) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith('s') && !/(ss|us|is)$/.test(w)) return w.slice(0, -1);
  return w;
}

/** The content words of a text (3+ letters, plurals folded, no stopwords). */
function cueTerms(text) {
  const out = new Set();
  for (const w of String(text || '').toLowerCase().match(/[a-z0-9]{3,}/g) || []) {
    const f = foldPlural(w);
    if (!CUE_STOPWORDS.has(w) && !CUE_STOPWORDS.has(f)) out.add(f);
  }
  return out;
}

/** Two words meet when equal, or when the shorter (4+ letters) begins the longer, at most 3 letters apart. */
function termsMeet(a, b) {
  if (a === b) return true;
  const [s, l] = a.length <= b.length ? [a, b] : [b, a];
  return s.length >= 4 && l.length - s.length <= 3 && l.startsWith(s);
}

function setHasTerm(set, t) {
  if (set.has(t)) return true;
  for (const u of set) if (termsMeet(t, u)) return true;
  return false;
}

/**
 * Each topic's terms from the store: its name, and its patterns' summaries and
 * rules (not their evidence, which is long and incidental).
 * @returns {Map<string, {name: Set<string>, text: Set<string>}>}
 */
function topicTermsFromStore(sourceRoot) {
  const { extractFieldSection } = require('./learn-lint.cjs');
  const text = new Map();
  for (const p of collectAllPatterns(sourceRoot)) {
    const prev = text.get(p.topic) || '';
    text.set(p.topic, `${prev}\n${p.summary}\n${extractFieldSection(p.body, 'Rule')}`);
  }
  const out = new Map();
  for (const [topic, t] of text) out.set(topic, { name: cueTerms(topic.replace(/-/g, ' ')), text: cueTerms(t) });
  return out;
}

/** How well a topic matches the cue: 2 per cue term in its name, 1 per term in its text. */
function cueScore(cue, terms) {
  if (!terms) return 0;
  let s = 0;
  for (const t of cue) s += setHasTerm(terms.name, t) ? 2 : setHasTerm(terms.text, t) ? 1 : 0;
  return s;
}

/**
 * Query: what topics should agent X load at this point?
 *
 * With `opts.cue` and `opts.topicTerms`, topics are matched to the task (mode
 * `cue`): every topic scoring at least half the best match is a candidate
 * whatever its role relevance, ranked by cue score, then relevance, then size;
 * the rest are not loaded. When nothing matches, or there is no cue, the role
 * ranking applies (mode `role`): relevance, then smallest first.
 *
 * @param {object} index - the index object
 * @param {object} opts
 * @param {string} opts.agent - 'planner' | 'executor' | 'verifier' | 'reviewer'
 * @param {string} [opts.minRelevance] - 'high' | 'medium' | 'low' (default 'medium'; role mode)
 * @param {number} [opts.tokenBudget] - max tokens to fit (default 5000)
 * @param {string} [opts.cue] - the phase objective and the files it touches
 * @param {Map} [opts.topicTerms] - from topicTermsFromStore()
 * @returns {object} { selected: [{name, scope, file, tokens, relevance, cue_score?}], total_tokens, dropped: [...], mode }
 */
function topicsForAgent(index, opts) {
  const agent = opts.agent;
  const minLevel = opts.minRelevance || 'medium';
  const budget = opts.tokenBudget || 5000;
  const ranks = { high: 3, medium: 2, low: 1 };
  const minRank = ranks[minLevel] || 2;

  const cue = cueTerms(opts.cue);
  const scored = index.topics.map(t => {
    const rel = (t.agent_relevance || {})[agent] || 'low';
    return { ...t, _relevance: rel, _rank: ranks[rel] || 1, _cue: cue.size ? cueScore(cue, opts.topicTerms && opts.topicTerms.get(t.name)) : 0 };
  });
  // A topic must score at least half the best match: a single incidental shared
  // word should not load a topic beside the ones the task is about. On the golden
  // set (tests/fixtures/learn-cue-golden.json) this cut raised precision from
  // 0.22 to 0.37 for a recall of 0.76 instead of 0.81.
  const top = Math.max(0, ...scored.map(t => t._cue));
  const matched = scored.filter(t => t._cue > 0 && t._cue >= Math.ceil(top / 2));
  const mode = matched.length ? 'cue' : 'role';

  const ranked = mode === 'cue'
    ? matched.sort((a, b) => b._cue - a._cue || b._rank - a._rank || a.size_tokens_est - b.size_tokens_est)
    : scored.filter(t => t._rank >= minRank).sort((a, b) => b._rank - a._rank || a.size_tokens_est - b.size_tokens_est);

  const selected = [];
  const dropped = [];
  let total = 0;
  for (const t of ranked) {
    if (total + t.size_tokens_est > budget) {
      dropped.push({ name: t.name, scope: t.scope, tokens: t.size_tokens_est, relevance: t._relevance });
      continue;
    }
    selected.push({
      name: t.name,
      scope: t.scope,
      file: t.file,
      tokens: t.size_tokens_est,
      relevance: t._relevance,
      patterns: t.patterns,
      ...(mode === 'cue' ? { cue_score: t._cue } : {}),
    });
    total += t.size_tokens_est;
  }

  return {
    agent,
    min_relevance: minLevel,
    token_budget: budget,
    mode,
    ...(opts.cue ? { cue: opts.cue } : {}),
    selected,
    dropped,
    total_tokens: total,
  };
}

function cmdBuildIndex(sourceRoot) {
  const index = buildIndex(sourceRoot);
  const filePath = writeIndex(sourceRoot, index);
  return {
    written_to: filePath,
    topics: index.totals.topics,
    patterns: index.totals.patterns,
    total_tokens_est: index.totals.size_tokens_est,
    schema_version: index.schema_version,
  };
}

function cmdTopicsFor(sourceRoot, opts) {
  const index = readIndex(sourceRoot);
  const topicTerms = opts.cue ? topicTermsFromStore(sourceRoot) : undefined;
  return topicsForAgent(index, { ...opts, topicTerms });
}

module.exports = {
  buildIndex,
  writeIndex,
  readIndex,
  topicsForAgent,
  topicTermsFromStore,
  cueTerms,
  cmdBuildIndex,
  cmdTopicsFor,
  INDEX_PATH_REL,
  RELEVANCE,
};
